{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Levocetirizine, a zwitterionic second-generation antihistamine, showed the lowest cerebral H1-receptor occupancy by PET and a low ability to cross the BBB, directly supporting poor CNS access for this antihistamine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DiPOA, which combines a diphenylpropyl piperidine with a carboxylate, had a brain-to-plasma ratio of only 0.019, demonstrating that a zwitterionic diphenyl-substituted piperidine architecture can have extremely low CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A basic radiotracer showed negligible baseline brain uptake that increased dramatically after ABC-transporter inhibition, indicating P-gp/ABC efflux restricts CNS access; fexofenadine is a known P-gp substrate with the same liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A zwitterionic compound exhibited brain/blood ratios of only 0.04-0.10 in rats, attributed to zwitterionic structure and high plasma protein/cell binding preventing effective BBB diffusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ramiprilat, a polar dicarboxylate, had a free CSF/plasma ratio of about 0.02 after IV dosing, showing very slow and poor BBB crossing for ionizable carboxylate-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "D-ritalinic acid could not be detected in the brain after oral administration of racemic methylphenidate, consistent with poor BBB penetration of a zwitterionic amino-acid-like metabolite.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is fexofenadine, a zwitterionic second-generation antihistamine with a carboxylic acid and basic piperidine. High-transfer experimental analogues—especially levocetirizine (same class), DiPOA (diphenylpiperidine carboxylate), and an ABC-efflux substrate—show very low brain/CSF penetration. Fexofenadine is also a known P-gp substrate, so meaningful CNS access is unlikely; prediction: fail.",
  "evidence_gaps": [
    "No direct fexofenadine brain/CSF measurement is included in the retrieved evidence set.",
    "Most quantitative evidence is from rodent models; human CNS exposure is inferred from class/efflux behavior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

